using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];

    [Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
    public static string WebSearch(string query)
    {
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        // Simulated search results for demonstration purposes.
        return query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") =>
                """
                1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
                2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
                3. IBM launched a 1,121-qubit processor (Condor) in 2023 and targets error-corrected systems by 2029.
                4. Key applications include cryptography, drug discovery, optimization, and materials science.
                5. Major challenges remain: decoherence, error rates, and extreme cooling requirements.
                """,
            var q when q.Contains("application") || q.Contains("use case") =>
                """
                1. Drug discovery: simulating molecular interactions to accelerate pharmaceutical research.
                2. Financial modeling: portfolio optimization and risk analysis at unprecedented scale.
                3. Cryptography: Shor's algorithm threatens RSA; post-quantum cryptography is being standardized.
                4. Climate modeling: more accurate simulations of atmospheric and oceanic systems.
                5. Supply chain: solving complex logistics optimization problems.
                """,
            _ =>
                $"Search results for '{query}': Various articles found discussing the topic with multiple perspectives and recent developments."
        };
    }

    [Description("Save a research note for later summarization. Use this to record key findings.")]
    public static string SaveNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

// --- Main Program ---

Console.WriteLine("Research Agent Starting...\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "test-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT");

OpenAIClientOptions? options = null;
if (endpoint is not null)
{
    options = new OpenAIClientOptions { Endpoint = new Uri(endpoint) };
}

var openAiClient = new OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), options);

IChatClient chatClient = openAiClient
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.WebSearch),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"Researching topic: \"{topic}\"\n");
Console.WriteLine(new string('-', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for information (make 2-3 searches with different angles)
        2. Saving important findings as notes using the SaveNote tool
        3. After researching, retrieve your notes and provide a well-structured summary

        Be thorough but concise. Always save key findings before summarizing.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, tools);

Console.WriteLine(new string('-', 50));
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

